import { TextEncoder } from "node:util";

/**
 * Compare two strings in constant time for security purposes.
 * Uses UTF-8 byte comparison to ensure proper handling of Unicode characters.
 * 
 * @param a - First string to compare
 * @param b - Second string to compare
 * @returns true if strings are equal, false otherwise
 */
export function timingSafeEqual(a: string, b: string): boolean {
  // Use TextEncoder to convert strings to UTF-8 bytes
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Constant-time comparison
  const len = Math.max(aBytes.length, bBytes.length);
  let result = 0;

  for (let i = 0; i < len; i++) {
    // Use bitwise XOR and OR to avoid early returns
    result |= aBytes[i] ^ bBytes[i];
  }

  // Return true only if all bytes are equal (result is 0)
  return result === 0;
}

